/* =========================================================
 COMPLETE FUNCTIONS DASHBOARD - Lesson 6 Capstone
 Uses: Declaration, Params, Return, Default, Arrow, Scope, Callbacks
========================================================= */

const TOTAL_LESSONS = 10;
const XP_PER_LESSON = 50;
const COURSE_ID = "javascript"; // Global scope

let lessons = [
 {id: 1, title: 'Introduction to JavaScript', learn: 'Understand JS', summary: 'Learn syntax', xp: 100},
 {id: 2, title: 'Variables and Data Types', learn: 'Store info', summary: 'Learn let, const', xp: 100},
 {id: 3, title: 'Operators', learn: 'Math and logic', summary: 'Master operators', xp: 100},
 {id: 4, title: 'Conditions', learn: 'Decisions', summary: 'Learn if/else', xp: 100},
 {id: 5, title: 'Loops', learn: 'Repetition', summary: 'Learn for, while', xp: 100}
];

// Function 1: Pure function with default params - calculates progress
function calculateProgress(completed = 0, total = TOTAL_LESSONS) {
 // Block scope inside function
 let safeCompleted = Math.min(total, Math.max(0, Number(completed) || 0));
 let percent = Math.round((safeCompleted / total) * 100);
 let text = `${safeCompleted} / ${total} completed`;
 return { completed: safeCompleted, total, percent, text }; // Return object
}

// Function 2: Pure function - gets status
function getStatus(lessonId, completed) {
 if (lessonId <= completed) return "completed";
 if (lessonId === completed + 1) return "current";
 return "locked";
}

// Function 3: Arrow function short - gets badge (pure)
const getBadge = (status) => {
 switch (status) {
 case "completed": return { text: "Completed", color: "#4ade80", icon: "✅" };
 case "current": return { text: "Current", color: "#f7df1e", icon: "▶" };
 default: return { text: "Locked", color: "#94a3b8", icon: "🔒" };
 }
};

// Function 4: Creates card - returns object with callback
function createLessonCard(lesson, completed) {
 let status = getStatus(lesson.id, completed); // Call other function
 let badge = getBadge(status); // Call arrow function
 let buttonText = status === "locked"? "Locked" : status === "completed"? "Review" : "Start Lesson";

 // Return card with onClick callback - closure over lesson and status
 return {
 id: lesson.id,
 title: lesson.title,
 status,
 badge,
 buttonText,
 xp: lesson.xp,
 onClick: () => { // Arrow callback - closure
 if (status!== "locked") {
 console.log(`→ Navigating to lesson.html?course=${COURSE_ID}&lesson=${lesson.id}`);
 return true;
 } else {
 console.log(`🔒 Lesson ${lesson.id} locked - need ${completed + 1} first`);
 return false;
 }
 }
 };
}

// Function 5: Side effect - updates stats (no return)
function updateStats(data) {
 // Function scope
 let xp = Number(data.xp || 0);
 let coins = Number(data.coins || 0);
 let xpText = `${xp.toLocaleString()} XP`;
 let coinsText = coins.toLocaleString();
 console.log(`📊 Stats: ${xpText}, ${coinsText} coins`);
 // No return - side effect (would update DOM in real dashboard)
}

// Function 6: Side effect with loop and callback param - renders lessons
function renderLessons(completed, onCardClick = null) { // Default param for callback
 console.log(`\n📚 Rendering ${lessons.length} lessons (completed=${completed}):`);
 let grid = [];

 // forEach with arrow callback - your dashboard way
 lessons.forEach(lesson => {
 let card = createLessonCard(lesson, completed);
 grid.push(card);
 let icon = card.badge.icon;
 console.log(` ${icon} ${card.id}. ${card.title} - ${card.status.toUpperCase()} - [${card.buttonText}]`);

 // If onCardClick callback provided, simulate click for current lesson
 if (onCardClick && card.status === "current") {
 // Don't auto-click, just show that callback exists
 }
 });

 console.log(`✅ Rendered ${grid.length} cards`);
 return grid;
}

// Function 7: Higher order function - takes callback
function processLessons(lessons, completed, callback) {
 // Callback called for each lesson
 lessons.forEach(lesson => {
 let card = createLessonCard(lesson, completed);
 callback(card); // Call passed callback
 });
}

// Function 8: Async function - simulates Firebase load
async function loadUserData(user = null) { // Default param
 await new Promise(r => setTimeout(r, 100)); // Simulate network
 if (!user) {
 return { xp: 0, coins: 0, completed: 0 };
 }
 return { xp: 120, coins: 30, completed: 2 };
}

