console.log(`Course: ${COURSE_ID}, Total: ${TOTAL_LESSONS}`);

// Load data (async)
loadUserData({uid: 'user123'}).then(data => {
 console.log(`\n👤 User data loaded: XP=${data.xp}, Coins=${data.coins}, Completed=${data.completed}`);

 let progress = calculateProgress(data.completed, TOTAL_LESSONS);
 console.log(`📈 Progress: ${progress.text} - ${progress.percent}%`);

 updateStats(data);

 let grid = renderLessons(data.completed);

 console.log("\n--- Testing Card Click Callbacks ---");
